mapper.select:
SELECT 
FROM sys_operation_log l
LEFT JOIN sys_user u ON u.id = l.user_id


        AND l.user_id = #{query.userId}


        AND l.operation = #{query.operation}


        AND l.result = #{query.result}


        AND l.created_at >= #{query.createdFrom}


        AND l.created_at < #{query.createdTo}


ORDER BY l.created_at DESC, l.id DESC
